SELECT COUNT(*) AS Stg_Customers_Count FROM Stg_Customers;
SELECT COUNT(*) AS Stg_Sales_Count FROM Stg_Sales;
SELECT COUNT(*) AS DimCustomer_Count FROM DimCustomer;
SELECT COUNT(*) AS DimProduct_Count FROM DimProduct;
SELECT COUNT(*) AS DimDate_Count FROM DimDate;
SELECT COUNT(*) AS FactSales_Count FROM FactSales;

SELECT TOP 10
    f.SaleID,
    d.FullDate,
    c.CustomerName,
    c.Region,
    p.ProductCode,
    f.Quantity,
    f.UnitPrice,
    f.TotalPrice
FROM FactSales f
JOIN DimCustomer c ON f.CustomerKey = c.CustomerKey
JOIN DimProduct p ON f.ProductKey = p.ProductKey
JOIN DimDate d ON f.DateKey = d.DateKey;
